sys_ui_action.script:
// Map only the specified fields
var person = current.getValue('people');

var sys_id = current.sys_id;
current.state = 1; // New

current.assignment_group = 'f6cc6838d7b122004f1e82285e610317'; //Billing Support
current.assigned_to = '';
current.sys_class_name = 'sn_customerservice_finance_email_case';

var transformDate = new GlideDateTime();
current.work_notes = 'Case transformed into a Finance case on ' + transformDate.getDisplayValue() + ' by ' + gs.getUserDisplayName();

current.update();

var financeVersionGR = new GlideRecord('sn_customerservice_finance_email_case');
financeVersionGR.get(sys_id);
financeVersionGR.setValue('category', '');
financeVersionGR.setValue('subcategory', '');

if (person != null && person != undefined) {
    //if there are multiple people, then take the first and put it in person, add the rest to watch list
    var split_person = person.split(',');
    if (split_person.length > 1) {
        financeVersionGR.setValue('u_person', split_person.shift());
        financeVersionGR.setValue('watch_list', split_person);
    } else
        financeVersionGR.setValue('u_person', person);
}
financeVersionGR.setValue('assigned_to', '');
financeVersionGR.update();

var emailGR = new GlideRecord('sys_email');
emailGR.addEncodedQuery('instance=' + sys_id);
emailGR.query();

while (emailGR.next()) {
    emailGR.setValue('target_table', 'sn_customerservice_finance_email_case');
    emailGR.update();
}

var attachGR = new GlideRecord('sys_attachment');
attachGR.addEncodedQuery('table_sys_id=' + sys_id);
attachGR.query();

while (attachGR.next()) {
    attachGR.setValue('table_name', 'sn_customerservice_finance_email_case');
    attachGR.update();
}

action.setRedirectURL("sn_customerservice_finance_email_case.do?sys_id=" + financeVersionGR.getUniqueValue());
